    if(mode==='recover') form=`<div class="eyebrow">Account recovery</div><h2>Get back in.</h2><p>Use a saved recovery code or a reset credential issued by the owner. All existing sessions will be signed out.</p><form data-form="recover">${field('username','Username','','text','required autocomplete="username"')}${select('recovery_method','Recovery method',[['recovery_code','Recovery code'],['reset_token','Owner reset credential']],'recovery_code')}${field('credential','Recovery credential','','text','required autocomplete="off"')}${field('new_password','New password','','password','required minlength="12" autocomplete="new-password"')}<div class="form-message"></div><button class="btn primary wide" type="submit">Reset password</button></form><div class="auth-links"><button class="text-button" data-auth="login">Back to sign in</button></div>`;
